/* Generated by build-pwa.mjs after all static HTML transforms. */
const BUILD = /* BUILD_CONFIG */ {};
const CACHE_PREFIX = `diagram-desk:${BUILD.base}:`;
const CACHE_NAME = `${CACHE_PREFIX}${BUILD.version}`;
const ENTRIES = new Map(BUILD.entries.map(entry => [entry.url, entry]));

function cachePath(pathname) {
  const path = pathname.replace(/\/index\.html$/, '/');
  if (ENTRIES.has(path)) return path;
  if (ENTRIES.has(`${path}/`)) return `${path}/`;
  return null;
}

async function verifiedResponse(entry) {
  const response = await fetch(new Request(entry.url, {
    cache: 'reload', credentials: 'same-origin', redirect: 'error',
    signal: AbortSignal.timeout(30000),
  }));
  return verifyResponse(entry, response);
}

async function verifyResponse(entry, response) {
  if (!response || !response.ok || response.type === 'opaque') throw new Error(`Cannot cache ${entry.url}`);
  const hash = await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer());
  const actual = Array.from(new Uint8Array(hash), byte => byte.toString(16).padStart(2, '0')).join('');
  if (actual !== entry.sha256) throw new Error(`Build changed while caching ${entry.url}`);
  return response;
}

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    let createdCache = false;
    try {
      const existingCache = (await caches.keys()).includes(CACHE_NAME);
      const cache = await caches.open(CACHE_NAME);
      createdCache = !existingCache;
      const pending = [...BUILD.entries];
      const workers = Array.from({ length: 4 }, async () => {
        while (pending.length) {
          const entry = pending.shift();
          const response = await verifiedResponse(entry);
          if (existingCache) {
            // A rollback can install while this same release still controls tabs.
            // Treat its cache as read-only, including when installation fails.
            await verifyResponse(entry, await cache.match(entry.url));
          } else {
            await cache.put(entry.url, response);
          }
        }
      });
      const results = await Promise.allSettled(workers);
      const failed = results.find(result => result.status === 'rejected');
      if (failed) throw failed.reason;
      // Keep the normal waiting phase. Existing tabs retain their complete release.
    } catch (error) {
      if (createdCache) await caches.delete(CACHE_NAME);
      throw error;
    }
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME).map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

function unavailable(navigation, status = 503) {
  const body = navigation
    ? `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Offline | Diagram Desk</title><main><h1>This page is unavailable offline.</h1><p>Open the saved <a href="${BUILD.base}">Diagram Desk library</a>, or reconnect and try again.</p></main></html>`
    : 'This resource is unavailable offline. Reconnect and try again.';
  return new Response(body, { status, headers: { 'Content-Type': navigation ? 'text/html; charset=utf-8' : 'text/plain; charset=utf-8' } });
}

self.addEventListener('fetch', event => {
  const { request } = event;
  const url = new URL(request.url);
  const withinBase = url.pathname === BUILD.base.slice(0, -1) || url.pathname.startsWith(BUILD.base);
  if (request.method !== 'GET' || url.origin !== self.location.origin || !withinBase) return;
  const path = cachePath(url.pathname);
  if (path) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE_NAME);
      const cached = await cache.match(path);
      if (cached) return cached;
      try {
        // Recover an evicted entry only if it still belongs to this release.
        const response = await verifiedResponse(ENTRIES.get(path));
        await cache.put(path, response.clone());
        return response;
      } catch {
        return unavailable(request.mode === 'navigate');
      }
    })());
  } else if (request.mode === 'navigate') {
    event.respondWith(fetch(request).catch(() => unavailable(true, 404)));
  }
});

self.addEventListener('message', event => {
  if (event.data?.type === 'ACTIVATE_UPDATE') {
    event.waitUntil(self.skipWaiting());
    return;
  }
  if (event.data?.type !== 'PWA_STATUS' || !event.ports[0]) return;
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    const keys = new Set((await cache.keys()).map(request => new URL(request.url).pathname));
    const ready = BUILD.entries.every(entry => keys.has(entry.url));
    event.ports[0].postMessage({ type: 'PWA_STATUS', version: BUILD.version, ready, entryCount: BUILD.entries.length, totalBytes: BUILD.totalBytes });
  })());
});
